def normalize_strings(items):
    if not items:
        return ''
    return ''.join(str(item).strip() for item in items)

# Validation examples
assert normalize_strings([" hello ", 42, " world "]) == 'hello42world'
assert normalize_strings([]) == ''
assert normalize_strings(["  a  ", "  b  "]) == 'ab'

